import { z } from 'zod';
import type { Account } from './account';
import { ProfileProviderSchema } from './design-profile';
import { ReferenceDiscoverySchema } from './reference-onboarding';
import { AuthenticatedReferenceProviderSchema } from './reference-connectors';
import {
  LibraryProjectPreviewSchema,
  LibraryProjectSchema,
} from './project-library';

export const ErrorResponseSchema = z.object({ error: z.string() });
export type ErrorResponse = z.infer<typeof ErrorResponseSchema>;

export const VariantsErrorResponseSchema = z.object({
  errorCode: z.string(),
  message: z.string(),
});
export type VariantsErrorResponse = z.infer<typeof VariantsErrorResponseSchema>;

export const SupportTicketErrorResponseSchema = z.object({
  error: z.string().optional(),
  details: z
    .union([
      z.string(),
      z.object({
        formErrors: z.array(z.string()).optional(),
        fieldErrors: z
          .record(z.string(), z.array(z.string()).optional())
          .optional(),
      }),
    ])
    .optional(),
});
export type SupportTicketErrorResponse = z.infer<
  typeof SupportTicketErrorResponseSchema
>;

export const BrowserSessionResponseSchema = z.object({
  token: z.string().min(1),
});
export type BrowserSessionResponse = z.infer<
  typeof BrowserSessionResponseSchema
>;

export const SignInBrowserLaunchResponseSchema = z.object({
  authUrl: z.string().url(),
  sessionId: z.string().min(1),
  pollSecret: z.string().min(1),
  isLaunched: z.boolean(),
});
export type SignInBrowserLaunchResponse = z.infer<
  typeof SignInBrowserLaunchResponseSchema
>;

export const LibraryViewLaunchResponseSchema = z.object({
  url: z.string().url(),
});
export type LibraryViewLaunchResponse = z.infer<
  typeof LibraryViewLaunchResponseSchema
>;

export const IntegrationBrowserLaunchResponseSchema = z.object({
  authUrl: z.string().url(),
  isLaunched: z.boolean(),
});
export type IntegrationBrowserLaunchResponse = z.infer<
  typeof IntegrationBrowserLaunchResponseSchema
>;

export const DesignLibraryEntriesResponseSchema = z.object({
  entries: z.array(
    z.object({
      referenceId: z.string(),
      url: z.string().url(),
    }),
  ),
});
export type DesignLibraryEntriesResponse = z.infer<
  typeof DesignLibraryEntriesResponseSchema
>;

export const LibraryProjectListResponseSchema = z.object({
  projects: z.array(LibraryProjectSchema),
});
export type LibraryProjectListResponse = z.infer<
  typeof LibraryProjectListResponseSchema
>;

export const LibraryProjectResponseSchema = z.object({
  project: LibraryProjectSchema,
});
export type LibraryProjectResponse = z.infer<
  typeof LibraryProjectResponseSchema
>;

export const LibraryProjectRemovalResponseSchema = z.object({
  projectId: z.string(),
});
export type LibraryProjectRemovalResponse = z.infer<
  typeof LibraryProjectRemovalResponseSchema
>;

export const LibraryProjectPreviewResponseSchema = z.object({
  preview: LibraryProjectPreviewSchema.nullable(),
});
export type LibraryProjectPreviewResponse = z.infer<
  typeof LibraryProjectPreviewResponseSchema
>;

export const FolderSelectionResponseSchema = z.object({
  projectPath: z.string().nullable(),
});
export type FolderSelectionResponse = z.infer<
  typeof FolderSelectionResponseSchema
>;

export const ProjectRuntimeResponseSchema = z.object({
  editorUrl: z.string(),
});
export type ProjectRuntimeResponse = z.infer<
  typeof ProjectRuntimeResponseSchema
>;

export const DirectionPreviewResponseSchema = z.object({ url: z.string() });
export type DirectionPreviewResponse = z.infer<
  typeof DirectionPreviewResponseSchema
>;

export const DirectionUpdateResponseSchema = z.object({
  saved: z.literal(true),
});
export type DirectionUpdateResponse = z.infer<
  typeof DirectionUpdateResponseSchema
>;

export const ViewNavigationSchema = z.object({
  requestId: z.string(),
  sequence: z.number(),
  projectId: z.string().optional(),
  sessionId: z.string().optional(),
  variantId: z.string().optional(),
});
export type ViewNavigation = z.infer<typeof ViewNavigationSchema>;

export const ViewNavigationsResponseSchema = z.object({
  navigations: z.array(ViewNavigationSchema),
});
export type ViewNavigationsResponse = z.infer<
  typeof ViewNavigationsResponseSchema
>;

export const NavigationAcknowledgementResponseSchema = z.object({
  acknowledged: z.boolean(),
});
export type NavigationAcknowledgementResponse = z.infer<
  typeof NavigationAcknowledgementResponseSchema
>;

export const ReferenceProfileStatusResponseSchema = z.object({
  profile: z.object({
    isEnabled: z.boolean(),
    autonomousReferences: z.boolean(),
  }),
  sources: z.array(
    z.object({
      provider: ProfileProviderSchema,
      title: z.string(),
      url: z.string().nullable(),
    }),
  ),
});
export type ReferenceProfileStatusResponse = z.infer<
  typeof ReferenceProfileStatusResponseSchema
>;

export const ReferenceDiscoveryResponseSchema = z.union([
  ReferenceDiscoverySchema,
  z.object({
    status: z.literal('authorization_required'),
    provider: AuthenticatedReferenceProviderSchema,
    authUrl: z.string().url(),
    message: z.string(),
  }),
]);

export const ReferenceImportPlanSummarySchema = z.object({
  id: z.string(),
  revision: z.string(),
  collectionCount: z.number(),
  referenceCount: z.number(),
  imageCount: z.number(),
  reusableCount: z.number(),
  unsupportedCount: z.number(),
  scopeDisclosure: z.string(),
  usageDisclosure: z.string(),
});
export type ReferenceImportPlanSummary = z.infer<
  typeof ReferenceImportPlanSummarySchema
>;

export const AccountResponseSchema: z.ZodType<Account> = z.object({
  isAuthenticated: z.boolean(),
  email: z.string().optional(),
  name: z.string().optional(),
  userId: z.string().optional(),
});

const VariantsUiStateKeySchema = z.string().min(1).max(500);

export const VariantsUiStateSchema = z.object({
  pinned: z.array(VariantsUiStateKeySchema).max(1000),
  order: z.object({
    groups: z.array(VariantsUiStateKeySchema).max(1000),
    rows: z.record(z.string(), z.array(VariantsUiStateKeySchema).max(1000)),
  }),
});
export type VariantsUiState = z.infer<typeof VariantsUiStateSchema>;

export const VariantsUiStateResponseSchema = z.object({
  projectPath: z.string(),
  uiState: VariantsUiStateSchema,
});
export type VariantsUiStateResponse = z.infer<
  typeof VariantsUiStateResponseSchema
>;

export const VariantsUiStateUpdateSchema = z.object({
  uiState: VariantsUiStateSchema,
  projectPath: z.string().optional(),
});
